state.example:
// client
const state = kcds.players.Weapons.state();
if (state && state.drawn) {
  console.log(`set ${state.slot + 1} is drawn`);
}

state.exampleCs:
// client
var state = Weapons.State();
if (!state.IsNull && state["drawn"].AsBool())
{
    Log.Info($"set {state["slot"].AsNumber() + 1} is drawn");
}

draw.example:
// client: key 3 selects and draws the third set, and holsters it when pressed again
const { Weapons } = kcds.players;

kcds.ui.Controls.blockAction('action_qam_3');
kcds.ui.Key.bind('3', () => {
  const why = Weapons.select(2) ?? Weapons.toggle();
  if (why) {
    kcds.ui.Hud.showNotification(`Cannot: ${why}`);
  }
});

draw.exampleCs:
// client: key 3 selects and draws the third set, and holsters it when pressed again
Controls.BlockAction("action_qam_3");
Key.Bind("3", new Action(() =>
{
    var why = Weapons.Select(2) ?? Weapons.Toggle();
    if (why != null)
    {
        Hud.ShowNotification($"Cannot: {why}");
    }
}));
